import {Button, LinkButton} from '@primer/styled-react'
import {useState} from 'react'
import {FormDialog} from './FormDialog'
import {testIdProps} from '@github-ui/test-id-props'

import {FormMode} from './types'
import type {TableActionProps} from './types'

export const TableAction = ({
  url,
  mode,
  message,
  useDialog,
  isEditableInScope,
  publicKey,
  keyId,
  tableDataUpdater,
}: TableActionProps) => {
  const variant = isEditableInScope ? 'primary' : 'default'
  const [newItemDialogOpen, setNewItemDialogOpen] = useState(false)

  if (url) {
    if (useDialog) {
      // In this case, have a semantic <button> -- the URL represents where the dialog sends a verified fetch request
      // for auth reasons, not a literal page navigation
      return (
        <>
          <Button
            variant="default"
            sx={{fontSize: 1, ':hover': {textDecoration: 'none'}}}
            onClick={() => setNewItemDialogOpen(true)}
            {...testIdProps('create-new-item-form-button')}
          >
            {message}
          </Button>
          {newItemDialogOpen && (
            <FormDialog
              mode={mode}
              onClose={() => setNewItemDialogOpen(false)}
              tableDataUpdater={tableDataUpdater}
              formMode={FormMode.add}
              url={url}
              publicKey={publicKey}
              keyId={keyId}
              rowId={''}
            />
          )}
        </>
      )
    } else {
      return (
        <LinkButton variant={variant} sx={{fontSize: 1, ':hover': {textDecoration: 'none'}}} href={url}>
          {message}
        </LinkButton>
      )
    }
  } else {
    // Non-admins do not have a table action
    return <></>
  }
}

export default TableAction
